@namespace sv_b2b7ba4c1403478580e4f8ad79547a4b.Components.Chat
@using sv_b2b7ba4c1403478580e4f8ad79547a4b.Services

<aside class="channel-list">
    <h2 class="channel-list__title">Channels</h2>
    <ul class="channel-list__items">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == ActiveChannelId ? "channel-item--active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-item__header">
                    <span class="channel-item__name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="channel-item__badge">@channel.UnreadCount</span>
                    }
                </div>
                <span class="channel-item__desc">@Truncate(channel.Description, 50)</span>
            </li>
        }
    </ul>
</aside>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength)
        => text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    height: 100%;
    background: #1e1e2e;
    color: #cdd6f4;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

.channel-list__title {
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 1rem 0.75rem 0.5rem;
    color: #a6adc8;
    margin: 0;
}

.channel-list__items {
    list-style: none;
    margin: 0;
    padding: 0;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 0.75rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.1s;
}

.channel-item:hover {
    background: rgba(255,255,255,0.06);
}

.channel-item--active {
    background: rgba(255,255,255,0.1);
    border-left-color: #4a6cf7;
}

.channel-item__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-item__name {
    font-weight: 600;
    font-size: 0.875rem;
    color: #e0e0e0;
}

.channel-item__badge {
    background: #f38ba8;
    color: #1e1e2e;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 999px;
    min-width: 1.2rem;
    text-align: center;
}

.channel-item__desc {
    font-size: 0.75rem;
    color: #7f849c;
    display: block;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@namespace sv_b2b7ba4c1403478580e4f8ad79547a4b.Components.Chat
@using sv_b2b7ba4c1403478580e4f8ad79547a4b.Services

<div class="thread-panel">
    <div class="thread-panel__header">
        <h3 class="thread-panel__title">Thread</h3>
        <button class="thread-panel__close" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-panel__root">
            <span class="thread-panel__root-author">@RootMessage.Author</span>
            <p class="thread-panel__root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-panel__replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="thread-reply__header">
                        <span class="thread-reply__author">@reply.Author</span>
                        <span class="thread-reply__time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="thread-reply__content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread…" ButtonLabel="Reply" OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

