@namespace sv_b2b7ba4c1403478580e4f8ad79547a4b.Components.Chat
@using sv_b2b7ba4c1403478580e4f8ad79547a4b.Services

<aside class="channel-list">
    <h2 class="channel-list__title">Channels</h2>
    <ul class="channel-list__items">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == ActiveChannelId ? "channel-item--active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-item__header">
                    <span class="channel-item__name"># @channel.Name</span>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="channel-item__badge">@channel.UnreadCount</span>
                    }
                </div>
                <span class="channel-item__desc">@Truncate(channel.Description, 50)</span>
            </li>
        }
    </ul>
</aside>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength)
        => text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    height: 100%;
    background: #1e1e2e;
    color: #cdd6f4;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

.channel-list__title {
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    padding: 1rem 0.75rem 0.5rem;
    color: #a6adc8;
    margin: 0;
}

.channel-list__items {
    list-style: none;
    margin: 0;
    padding: 0;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 0.75rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.1s;
}

.channel-item:hover {
    background: rgba(255,255,255,0.06);
}

.channel-item--active {
    background: rgba(255,255,255,0.1);
    border-left-color: #4a6cf7;
}

.channel-item__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-item__name {
    font-weight: 600;
    font-size: 0.875rem;
    color: #e0e0e0;
}

.channel-item__badge {
    background: #f38ba8;
    color: #1e1e2e;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 999px;
    min-width: 1.2rem;
    text-align: center;
}

.channel-item__desc {
    font-size: 0.75rem;
    color: #7f849c;
    display: block;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

