arguments.file_text:
@page "/chat"
@layout ChatLayout
@namespace sv_b2b7ba4c1403478580e4f8ad79547a4b.Components.Chat
@rendermode InteractiveServer
@using sv_b2b7ba4c1403478580e4f8ad79547a4b.Services
@inject IChatService ChatService

<div class="chat-page">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     ActiveChannelId="activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadRootMessage is null ? "chat-main--wide" : "")">
        @if (activeChannel is not null)
        {
            <div class="chat-main__header">
                <h2 class="chat-main__channel-name"># @activeChannel.Name</h2>
                <span class="chat-main__channel-desc">@activeChannel.Description</span>
            </div>

            <div class="chat-main__messages" @onscroll="HandleScroll">
                @if (isLoadingMore)
                {
                    <div class="chat-main__loading">Loading older messages…</div>
                }

                @foreach (var msg in messages)
                {
                    <MessageItem Message="msg"
                                 IsThreadStarter="@(msg.ReplyToId is null)"
                                 ReplyCount="@GetReplyCount(msg.Id)"
                                 OnOpenThread="() => OpenThread(msg)"
                                 OnReact="(emoji) => AddReaction(msg.Id, emoji)" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{activeChannel.Name}")"
                          ButtonLabel="Send"
                          OnSubmit="SendMessage" />
        }
        else
        {
            <div class="chat-main__empty">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> replyCountMap = new();

    private Channel? activeChannel;
    private int activeChannelId;
    private Message? threadRootMessage;

    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        replyCountMap = new();
        hasMoreMessages = true;
        threadRootMessage = null;
        threadReplies = [];

        await LoadMessages();
        _ = ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (batch.Count < PageSize)
            hasMoreMessages = false;

        messages.InsertRange(0, batch);
        BuildReplyCountMap();
    }

    private void BuildReplyCountMap()
    {
        replyCountMap.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            replyCountMap[rootId] = replyCountMap.GetValueOrDefault(rootId) + 1;
        }
    }

    private int GetReplyCount(int messageId)
        => replyCountMap.GetValueOrDefault(messageId);

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages.
        // The actual scroll-position check requires JS interop; here we provide
        // the hook. In a production app you would use a JS helper to detect
        // scrollTop === 0 and invoke this via DotNetObjectReference.
        if (!isLoadingMore && hasMoreMessages)
        {
            isLoadingMore = true;
            await LoadMessages();
            isLoadingMore = false;
        }
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(Message rootMessage)
    {
        // If the message is a reply, open the thread for its root
        var rootId = rootMessage.ReplyToId ?? rootMessage.Id;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootId) ?? rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootId);
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        messages.Add(reply);
        BuildReplyCountMap();
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Optimistic update: add/increment the reaction locally
        var msg = messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
    }
}

.chat-page {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Sidebar: ~20% */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

/* Main message area: fills remaining space */
.chat-main {
    flex: 55;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
}

.chat-main--wide {
    flex: 80;
}

.chat-main__header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.chat-main__channel-name {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.chat-main__channel-desc {
    font-size: 0.8rem;
    color: #777;
}

.chat-main__messages {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.chat-main__loading {
    text-align: center;
    padding: 0.75rem;
    font-size: 0.8rem;
    color: #999;
}

.chat-main__empty {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #aaa;
    font-size: 1rem;
}

/* Thread panel: ~25% */
.chat-thread {
    width: 25%;
    min-width: 260px;
    max-width: 380px;
    flex-shrink: 0;
}

